    pub fn open(
        config_file: &Path,
        registration_file: &Path,
        owner_pidfd: OwnedFd,
    ) -> io::Result<Self> {
        let config = read_root_json(config_file)?;
        let registration = read_root_json(registration_file)?;
        let service = open_registered_service(&config, &registration, &owner_pidfd)?;
        Ok(Self {
            config,
            registration,
            owner_pidfd,
            service,
            fresh_filesystem: false,
            root_admin: None,
            learning: None,
